/*
 * Host tests for drivers/s23usbc/s23usbc_pd.h: PDO/RDO codec parity with the Python reference
 * (vectors generated by usb_research/gen_s23usbc_c_vectors.py), PD message parsing, the 15-18 W
 * Fixed PDO sink policy, PPS request clamping, the OTG boost guard and DR/PR swap helpers.
 */
#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include "host_test.h"
#include "s23usbc/s23usbc_pd.h"
#define S23V_WANT_PD
#include "s23usbc_vectors.h"

#define N_ELEM(a) (sizeof(a) / sizeof((a)[0]))

static uint32_t fixed_pdo(uint32_t mv, uint32_t ma) { return ((mv / 50U) << 10) | (ma / 10U); }
static uint32_t pps_apdo(uint32_t min_mv, uint32_t max_mv, uint32_t ma)
{
    return (3U << 30) | ((max_mv / 100U) << 17) | ((min_mv / 100U) << 8) | (ma / 50U);
}

static void test_pdo_vectors(void)
{
    size_t i;
    for (i = 0; i < N_ELEM(k_pdo_decode_vectors); i++) {
        const S23V_PDO *v = &k_pdo_decode_vectors[i];
        S23PD_PDO p;
        uint32_t re = 0;
        memset(&p, 0, sizeof(p));
        int rc = S23PdDecodePdo(v->raw, &p);
        CHECK_EQ_U64(rc == S23USBC_OK, v->ok);
        if (rc != S23USBC_OK || !v->ok) continue;
        CHECK_EQ_U64(p.type, v->type);
        CHECK_EQ_U64(p.dual_role_power, v->dual_role_power);
        CHECK_EQ_U64(p.usb_suspend_supported, v->usb_suspend_supported);
        CHECK_EQ_U64(p.unconstrained_power, v->unconstrained_power);
        CHECK_EQ_U64(p.usb_comms_capable, v->usb_comms_capable);
        CHECK_EQ_U64(p.dual_role_data, v->dual_role_data);
        CHECK_EQ_U64(p.unchunked_ext_msg, v->unchunked_ext_msg);
        CHECK_EQ_U64(p.peak_current, v->peak_current);
        CHECK_EQ_U64(p.pps_power_limited, v->pps_power_limited);
        CHECK_EQ_U64(p.voltage_mv, v->voltage_mv);
        CHECK_EQ_U64(p.max_voltage_mv, v->max_voltage_mv);
        CHECK_EQ_U64(p.min_voltage_mv, v->min_voltage_mv);
        CHECK_EQ_U64(p.max_current_ma, v->max_current_ma);
        CHECK_EQ_U64(p.max_power_mw, v->max_power_mw);
        CHECK(S23PdEncodePdo(&p, &re) == S23USBC_OK);
        CHECK_EQ_U64(re, v->reencoded);
    }
    for (i = 0; i < N_ELEM(k_pdo_encode_vectors); i++) {
        const S23V_PDO_ENC *v = &k_pdo_encode_vectors[i];
        S23PD_PDO p;
        uint32_t out = 0xDEADBEEFU;
        memset(&p, 0, sizeof(p));
        p.type = (uint8_t)v->type;
        p.dual_role_power = (uint8_t)v->dual_role_power;
        p.usb_suspend_supported = (uint8_t)v->usb_suspend_supported;
        p.unconstrained_power = (uint8_t)v->unconstrained_power;
        p.usb_comms_capable = (uint8_t)v->usb_comms_capable;
        p.dual_role_data = (uint8_t)v->dual_role_data;
        p.unchunked_ext_msg = (uint8_t)v->unchunked_ext_msg;
        p.peak_current = (uint8_t)v->peak_current;
        p.pps_power_limited = (uint8_t)v->pps_power_limited;
        p.voltage_mv = v->voltage_mv;
        p.max_voltage_mv = v->max_voltage_mv;
        p.min_voltage_mv = v->min_voltage_mv;
        p.max_current_ma = v->max_current_ma;
        p.max_power_mw = v->max_power_mw;
        int rc = S23PdEncodePdo(&p, &out);
        CHECK_EQ_U64(rc == S23USBC_OK, v->ok);
        if (v->ok && rc == S23USBC_OK) CHECK_EQ_U64(out, v->raw);
    }
}

static void test_rdo_vectors(void)
{
    size_t i;
    for (i = 0; i < N_ELEM(k_rdo_encode_vectors); i++) {
        const S23V_RDO_ENC *v = &k_rdo_encode_vectors[i];
        S23PD_RDO r;
        uint32_t out = 0;
        memset(&r, 0, sizeof(r));
        r.object_position = (uint8_t)v->position;
        r.give_back = (uint8_t)v->flags[0];
        r.capability_mismatch = (uint8_t)v->flags[1];
        r.usb_comms_capable = (uint8_t)v->flags[2];
        r.no_usb_suspend = (uint8_t)v->flags[3];
        r.unchunked_ext_msg = (uint8_t)v->flags[4];
        r.operating_current_ma = v->operating_current_ma;
        r.limit_current_ma = v->limit_current_ma;
        r.operating_power_mw = v->operating_power_mw;
        r.limit_power_mw = v->limit_power_mw;
        r.output_voltage_mv = v->output_voltage_mv;
        int rc = S23PdEncodeRdo(&r, v->type, &out);
        CHECK_EQ_U64(rc == S23USBC_OK, v->ok);
        if (v->ok && rc == S23USBC_OK) CHECK_EQ_U64(out, v->raw);
    }
    for (i = 0; i < N_ELEM(k_rdo_decode_vectors); i++) {
        const S23V_RDO_DEC *v = &k_rdo_decode_vectors[i];
        S23PD_RDO r;
        memset(&r, 0, sizeof(r));
        int rc = S23PdDecodeRdo(v->raw, v->type, &r);
        CHECK_EQ_U64(rc == S23USBC_OK, v->ok);
        if (rc != S23USBC_OK || !v->ok) continue;
        CHECK_EQ_U64(r.object_position, v->position);
        CHECK_EQ_U64(r.give_back, v->flags[0]);
        CHECK_EQ_U64(r.capability_mismatch, v->flags[1]);
        CHECK_EQ_U64(r.usb_comms_capable, v->flags[2]);
        CHECK_EQ_U64(r.no_usb_suspend, v->flags[3]);
        CHECK_EQ_U64(r.unchunked_ext_msg, v->flags[4]);
        CHECK_EQ_U64(r.operating_current_ma, v->operating_current_ma);
        CHECK_EQ_U64(r.limit_current_ma, v->limit_current_ma);
        CHECK_EQ_U64(r.operating_power_mw, v->operating_power_mw);
        CHECK_EQ_U64(r.limit_power_mw, v->limit_power_mw);
        CHECK_EQ_U64(r.output_voltage_mv, v->output_voltage_mv);
    }
}

static void test_msg_header_and_parse(void)
{
    S23PD_MSG_HEADER h, d;
    uint16_t raw = 0;
    uint32_t objs[7];
    size_t n = 99;
    uint8_t buf[2 + 7 * 4];
    unsigned k;

    memset(&h, 0, sizeof(h));
    h.message_type = 1;          /* Source_Capabilities */
    h.spec_revision = 2;         /* PD 3.0 */
    h.port_power_role = 1;
    h.message_id = 5;
    h.num_data_objects = 3;
    CHECK(S23PdEncodeMsgHeader(&h, &raw) == S23USBC_OK);
    CHECK_EQ_U64(raw, 0x1U | (2U << 6) | (1U << 8) | (5U << 9) | (3U << 12));
    S23PdDecodeMsgHeader(raw, &d);
    CHECK(memcmp(&h, &d, sizeof(h)) == 0);
    h.num_data_objects = 8;
    CHECK(S23PdEncodeMsgHeader(&h, &raw) == S23USBC_E_RANGE);
    CHECK(S23PdEncodeMsgHeader(NULL, &raw) == S23USBC_E_ARG);

    /* 3 objects on the wire, LE */
    h.num_data_objects = 3;
    CHECK(S23PdEncodeMsgHeader(&h, &raw) == S23USBC_OK);
    buf[0] = (uint8_t)(raw & 0xFFU);
    buf[1] = (uint8_t)(raw >> 8);
    S23PdPutLe32(buf + 2, fixed_pdo(5000, 3000));
    S23PdPutLe32(buf + 6, fixed_pdo(9000, 2000));
    S23PdPutLe32(buf + 10, pps_apdo(3300, 11000, 3000));
    CHECK(S23PdParseDataMessage(buf, 14, &d, objs, &n) == S23USBC_OK);
    CHECK_EQ_U64(n, 3);
    CHECK_EQ_U64(objs[0], fixed_pdo(5000, 3000));
    CHECK_EQ_U64(objs[2], pps_apdo(3300, 11000, 3000));
    for (k = 0; k < 14; k++) CHECK(S23PdParseDataMessage(buf, k, &d, objs, &n) != S23USBC_OK);
    CHECK(S23PdParseDataMessage(buf, 15, &d, objs, &n) == S23USBC_E_LENGTH);
    buf[1] |= 0x80U;   /* extended */
    CHECK(S23PdParseDataMessage(buf, 14, &d, objs, &n) == S23USBC_E_TYPE);
    buf[1] = 0;        /* zero objects = control message */
    CHECK(S23PdParseDataMessage(buf, 2, &d, objs, &n) == S23USBC_E_TYPE);
    CHECK(S23PdParseDataMessage(NULL, 2, &d, objs, &n) == S23USBC_E_ARG);
}

static S23PD_SINK_POLICY policy(uint32_t mw, uint32_t mv, uint32_t ma)
{
    S23PD_SINK_POLICY p;
    memset(&p, 0, sizeof(p));
    p.max_power_mw = mw;
    p.max_voltage_mv = mv;
    p.max_current_ma = ma;
    return p;
}

static void test_select_fixed(void)
{
    S23PD_SELECTION s;
    S23PD_RDO r;
    S23PD_SINK_POLICY pol = policy(18000, 9000, 3000);
    const uint32_t caps[] = { fixed_pdo(5000, 3000), fixed_pdo(9000, 2000), fixed_pdo(15000, 1500),
                              pps_apdo(3300, 11000, 3000) };

    /* 9 V / 2 A = 18 W wins over 5 V / 3 A = 15 W; 15 V is above the voltage limit */
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_OK);
    CHECK_EQ_U64(s.object_position, 2);
    CHECK_EQ_U64(s.voltage_mv, 9000);
    CHECK_EQ_U64(s.current_ma, 2000);
    CHECK_EQ_U64(s.power_mw, 18000);
    CHECK(S23PdDecodeRdo(s.rdo, S23PD_PDO_FIXED, &r) == S23USBC_OK);
    CHECK_EQ_U64(r.object_position, 2);
    CHECK_EQ_U64(r.operating_current_ma, 2000);
    CHECK_EQ_U64(r.limit_current_ma, 2000);
    CHECK_EQ_U64(r.capability_mismatch, 0);

    /* 15 W cap: 9 V limited to 1660 mA (floored to 10 mA) = 14940 mW < 5 V/3 A = 15000 mW */
    pol = policy(15000, 9000, 3000);
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_OK);
    CHECK_EQ_U64(s.object_position, 1);
    CHECK_EQ_U64(s.power_mw, 15000);

    /* tie keeps the lower object position */
    const uint32_t tie[] = { fixed_pdo(5000, 3000), fixed_pdo(5000, 3000) };
    pol = policy(18000, 20000, 5000);
    CHECK(S23PdSelectFixed(tie, 2, &pol, &s) == S23USBC_OK);
    CHECK_EQ_U64(s.object_position, 1);

    /* capability mismatch flag when the best offer is below the requirement */
    pol = policy(18000, 5000, 3000);
    pol.required_mw = 18000;
    pol.usb_comms_capable = 1;
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_OK);
    CHECK_EQ_U64(s.capability_mismatch, 1);
    CHECK(S23PdDecodeRdo(s.rdo, S23PD_PDO_FIXED, &r) == S23USBC_OK);
    CHECK_EQ_U64(r.capability_mismatch, 1);
    CHECK_EQ_U64(r.usb_comms_capable, 1);

    /* invalid inputs */
    pol = policy(18000, 9000, 3000);
    CHECK(S23PdSelectFixed(caps, 0, &pol, &s) == S23USBC_E_LENGTH);
    CHECK(S23PdSelectFixed(caps, 8, &pol, &s) == S23USBC_E_LENGTH);
    CHECK(S23PdSelectFixed(caps + 1, 1, &pol, &s) == S23USBC_E_TYPE);   /* object 1 must be vSafe5V */
    pol = policy(20000, 9000, 3000);
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_E_POLICY);
    pol = policy(18000, 4000, 3000);
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_E_POLICY);
    pol = policy(18000, 9000, 0);
    CHECK(S23PdSelectFixed(caps, 4, &pol, &s) == S23USBC_E_POLICY);
    pol = policy(18000, 9000, 3000);
    CHECK(S23PdSelectFixed(NULL, 4, &pol, &s) == S23USBC_E_ARG);
    CHECK(S23PdSelectFixed(caps, 4, &pol, NULL) == S23USBC_E_ARG);
}

static void test_pps(void)
{
    S23PD_SELECTION s;
    S23PD_RDO r;
    const uint32_t caps[] = { fixed_pdo(5000, 3000), pps_apdo(3300, 11000, 3000), (3U << 30) | (1U << 28),
                              pps_apdo(11000, 3300, 3000) };

    CHECK(S23PdBuildPpsRequest(caps, 4, 2, 9010, 2010, 0, 0, 0, &s) == S23USBC_OK);
    CHECK_EQ_U64(s.voltage_mv, 9000);          /* floored to 20 mV */
    CHECK_EQ_U64(s.current_ma, 2000);          /* floored to 50 mA */
    CHECK(S23PdDecodeRdo(s.rdo, S23PD_PDO_PPS, &r) == S23USBC_OK);
    CHECK_EQ_U64(r.output_voltage_mv, 9000);
    CHECK_EQ_U64(r.operating_current_ma, 2000);
    CHECK_EQ_U64(r.object_position, 2);

    CHECK(S23PdBuildPpsRequest(caps, 4, 2, 20000, 9000, 0, 0, 0, &s) == S23USBC_OK);   /* clamp high */
    CHECK_EQ_U64(s.voltage_mv, 11000);
    CHECK_EQ_U64(s.current_ma, 3000);
    CHECK(S23PdBuildPpsRequest(caps, 4, 2, 1000, 1000, 0, 0, 0, &s) == S23USBC_OK);     /* clamp low */
    CHECK_EQ_U64(s.voltage_mv, 3300);
    CHECK(S23PdBuildPpsRequest(caps, 4, 2, 10000, 3000, 15000, 0, 0, &s) == S23USBC_OK); /* power cap */
    CHECK_EQ_U64(s.current_ma, 1500);
    CHECK(s.power_mw <= 15000);

    CHECK(S23PdBuildPpsRequest(caps, 4, 1, 9000, 2000, 0, 0, 0, &s) == S23USBC_E_TYPE);  /* fixed */
    CHECK(S23PdBuildPpsRequest(caps, 4, 3, 9000, 2000, 0, 0, 0, &s) != S23USBC_OK);      /* APDO type 1 */
    CHECK(S23PdBuildPpsRequest(caps, 4, 4, 9000, 2000, 0, 0, 0, &s) == S23USBC_E_RANGE); /* min > max */
    CHECK(S23PdBuildPpsRequest(caps, 4, 0, 9000, 2000, 0, 0, 0, &s) == S23USBC_E_RANGE);
    CHECK(S23PdBuildPpsRequest(caps, 4, 5, 9000, 2000, 0, 0, 0, &s) == S23USBC_E_RANGE);
    CHECK(S23PdBuildPpsRequest(caps, 4, 2, 9000, 40, 0, 0, 0, &s) == S23USBC_E_RANGE);   /* 0 mA */
    CHECK_EQ_U64(s.rdo, 0);
    CHECK(S23PdValidateObjectPosition(1, 0) == S23USBC_E_LENGTH);
    CHECK(S23PdValidateObjectPosition(7, 7) == S23USBC_OK);
    CHECK(S23PdValidateObjectPosition(8, 8) == S23USBC_E_LENGTH);
}

static void test_otg_guard(void)
{
    S23USBC_OTG_INPUTS in;
    memset(&in, 0, sizeof(in));
    in.partner_is_sink = 1;
    in.vsafe0v = 1;
    CHECK_EQ_U64(S23UsbcOtgEnableBlockers(&in), 0);
    CHECK_EQ_U64(S23UsbcOtgDisableReasons(&in), 0);

    in.vbus_det = 1;
    CHECK(S23UsbcOtgEnableBlockers(&in) & S23USBC_OTG_BLK_VBUS_PRESENT);
    CHECK_EQ_U64(S23UsbcOtgDisableReasons(&in), 0);   /* our own boost drives VBUS */
    in.vbus_det = 0;
    in.vsafe0v = 0;
    CHECK(S23UsbcOtgEnableBlockers(&in) & S23USBC_OTG_BLK_NOT_VSAFE0V);
    in.vsafe0v = 1;
    in.partner_is_sink = 0;
    CHECK(S23UsbcOtgEnableBlockers(&in) & S23USBC_OTG_BLK_NOT_SINK);
    CHECK(S23UsbcOtgDisableReasons(&in) & S23USBC_OTG_BLK_NOT_SINK);
    in.partner_is_sink = 1;
    in.water_detected = 1;
    CHECK(S23UsbcOtgDisableReasons(&in) & S23USBC_OTG_BLK_WATER);
    in.water_detected = 0;
    in.pr_swap_pending = 1;
    CHECK(S23UsbcOtgEnableBlockers(&in) & S23USBC_OTG_BLK_PR_SWAP);
    in.pr_swap_pending = 0;
    in.sink_contract = 1;
    CHECK(S23UsbcOtgEnableBlockers(&in) & S23USBC_OTG_BLK_SINKING);
    CHECK_EQ_U64(S23UsbcOtgEnableBlockers(NULL), S23USBC_OTG_BLK_ALL);

    /* register-derived fields: CC_STATUS1 = CCSBUSHORT=1, VCONNOCP, VSAFE0V set */
    memset(&in, 0, sizeof(in));
    CHECK(S23UsbcOtgInputsFromRegs(0x80U, (1U << 6) | (1U << 5) | (1U << 3), &in) == S23USBC_OK);
    CHECK_EQ_U64(in.vbus_det, 1);
    CHECK_EQ_U64(in.vsafe0v, 1);
    CHECK_EQ_U64(in.cc_sbu_short, 1);
    CHECK_EQ_U64(in.vconn_ocp, 1);
    in.partner_is_sink = 1;
    CHECK((S23UsbcOtgEnableBlockers(&in) & (S23USBC_OTG_BLK_SBU_SHORT | S23USBC_OTG_BLK_VCONN_OCP |
                                             S23USBC_OTG_BLK_VBUS_PRESENT)) ==
          (S23USBC_OTG_BLK_SBU_SHORT | S23USBC_OTG_BLK_VCONN_OCP | S23USBC_OTG_BLK_VBUS_PRESENT));
    CHECK(S23UsbcOtgInputsFromRegs(0x100U, 0, &in) != S23USBC_OK);
    CHECK(S23UsbcOtgInputsFromRegs(0, 0, NULL) == S23USBC_E_ARG);
}

static void test_swaps(void)
{
    S23USBC_WRITE_PLAN p;
    memset(&p, 0, sizeof(p));
    CHECK(S23UsbcEncodeSwapRequest(S23USBC_SWAP_DR, 0, &p) == S23USBC_OK);
    CHECK_EQ_U64(p.count, 2);
    CHECK_EQ_U64(p.w[0].reg, 0x21);
    CHECK_EQ_U64(p.w[0].len, 2);
    CHECK_EQ_U64(p.w[0].buf[0], 0x37);
    CHECK_EQ_U64(p.w[0].buf[1], 0x01);
    CHECK(S23UsbcEncodeSwapRequest(S23USBC_SWAP_PR, 0, &p) == S23USBC_OK);
    CHECK_EQ_U64(p.w[0].buf[1], 0x02);
    CHECK(S23UsbcEncodeSwapRequest(S23USBC_SWAP_MANUAL_ROLE, 0, &p) == S23USBC_OK);
    CHECK(S23UsbcEncodeSwapRequest(0x03, 0, &p) == S23USBC_E_RANGE);
    CHECK_EQ_U64(p.count, 0);

    CHECK_EQ_U64(S23UsbcDrSwapReady(1U << 4), 1);   /* PD_PSRDY */
    CHECK_EQ_U64(S23UsbcDrSwapReady(0), 0);
    CHECK(S23UsbcDrSwapReady(0x100U) < 0);
    CHECK_EQ_U64(S23UsbcPrSwapAllowed(1U << 4, 0), 1);
    CHECK_EQ_U64(S23UsbcPrSwapAllowed(1U << 4, 1), 0);   /* boost must be off first */
    CHECK_EQ_U64(S23UsbcPrSwapAllowed(0, 0), 0);
}

int main(void)
{
    test_pdo_vectors();
    test_rdo_vectors();
    test_msg_header_and_parse();
    test_select_fixed();
    test_pps();
    test_otg_guard();
    test_swaps();
    return test_report("test_s23usbc_pd");
}
